    /// <summary>Look up the property value of a code point.</summary>
    /// <param name="codePoint">The code point to look up.</param>
    /// <returns>The value, or <see cref="BidiClassValue.L"/> when the code point is unassigned.</returns>
    public static BidiClassValue Lookup(int codePoint)
    {
        int low = 0;
        int high = Starts.Length - 1;

        while (low <= high)
        {
            int middle = (low + high) >> 1;

            if (codePoint < Starts[middle])
            {
                high = middle - 1;
            }
            else if (codePoint > Ends[middle])
            {
                low = middle + 1;
            }
            else
            {
                return Values[middle];
            }
        }

        return Default;
    }
